const listAgreementsForExport = `-- name: ListAgreementsForExport :many
SELECT a.uuid, a.code, a.name, a.status, a.valid_from, a.valid_to, a.invoice_period, a.payment_term_days,
    a.open_account, a.credit_limit, a.coupon_eligible, a.currency, a.notes, a.created_at,
    c.company_title AS customer_company_title, b.code AS branch_code
FROM corporate_agreements a
JOIN customers c ON c.organization_id = a.organization_id AND c.id = a.customer_id
LEFT JOIN branches b ON b.organization_id = a.organization_id AND b.id = a.branch_id
WHERE a.organization_id = $1
  AND c.organization_id = $1
  AND a.deleted_at IS NULL
  AND ($2::bigint[] IS NULL OR a.branch_id IS NULL OR a.branch_id = ANY($2::bigint[]))
  AND ($3::text[] IS NULL OR a.status = ANY($3::text[]))
  AND ($4::uuid[] IS NULL OR c.uuid = ANY($4::uuid[]))
  AND (
    $5::text[] IS NULL
    OR (CASE WHEN a.valid_from > $6::date THEN 'upcoming'
             WHEN a.valid_to IS NOT NULL AND a.valid_to < $6::date THEN 'expired'
             ELSE 'current' END) = ANY($5::text[])
  )
  AND (
    $7::text IS NULL
    OR a.code ILIKE '%' || $7 || '%'
    OR a.name ILIKE '%' || $7 || '%'
    OR c.company_title ILIKE '%' || $7 || '%'
  )
ORDER BY a.code
LIMIT $8
`

