const listCustomerAgreementsForSale = `-- name: ListCustomerAgreementsForSale :many
SELECT a.uuid, a.code, a.name, a.invoice_period, a.open_account, a.credit_limit, a.coupon_eligible,
    a.payment_term_days, a.valid_from, a.valid_to, a.branch_id
FROM corporate_agreements a
JOIN customers c ON c.organization_id = a.organization_id AND c.id = a.customer_id
WHERE a.organization_id = $1
  AND c.organization_id = $1
  AND c.uuid = $2
  AND a.deleted_at IS NULL
  AND a.status = 'active'
  AND a.valid_from <= $3::date
  AND (a.valid_to IS NULL OR a.valid_to >= $3::date)
  AND ($4::bigint[] IS NULL OR a.branch_id IS NULL OR a.branch_id = ANY($4::bigint[]))
ORDER BY a.code
`

