const lockAgreement = `-- name: LockAgreement :one
SELECT a.id FROM corporate_agreements a
WHERE a.organization_id = $1
  AND a.id = $2
  AND a.deleted_at IS NULL
FOR UPDATE
`

type LockAgreementParams struct {
	OrganizationID int64 `json:"organization_id"`
	ID             int64 `json:"id"`
}

func (q *Queries) LockAgreement(ctx context.Context, arg LockAgreementParams) (int64, error) {
	row := q.db.QueryRow(ctx, lockAgreement, arg.OrganizationID, arg.ID)
	var id int64
	err := row.Scan(&id)
	return id, err
}

const lockAgreementCodes = `-- name: LockAgreementCodes :exec

SELECT pg_advisory_xact_lock(hashtextextended('agreements.codes:' || $1::bigint::text, 0))
`

// Corporate agreements (TEC-723, docs/design/corporate-agreements.md).
// Branch scope: an agreement with a managing branch is visible inside that
// branch's scope; a head office agreement (branch NULL) to everyone.
// Validity state (computed against :today, Istanbul calendar):
//
//	upcoming  valid_from > today
//	expired   valid_to < today
//	current   otherwise
func (q *Queries) LockAgreementCodes(ctx context.Context, organizationID int64) error {
	_, err := q.db.Exec(ctx, lockAgreementCodes, organizationID)
	return err
}

const nextAgreementNumber = `-- name: NextAgreementNumber :one
SELECT (COUNT(*) + 1)::bigint FROM corporate_agreements a WHERE a.organization_id = $1
`

func (q *Queries) NextAgreementNumber(ctx context.Context, organizationID int64) (int64, error) {
	row := q.db.QueryRow(ctx, nextAgreementNumber, organizationID)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

